-- Written to be re-runnable: production applies each statement on its own, so a run
-- interrupted part way must be able to start again from the top.
-- The exact saved value a traveller sent in answer to a detail (FIELD) evidence request, and the
-- decision made on it. Two new tables, nothing existing is touched; the pin is a reference to the
-- immutable fact_versions row, never a copy of the value. The two tables were generated by
-- drizzle-kit and made re-runnable here; the triggers at the end are hand-written and reuse the
-- function migration 0132 created. Until this runs the code finds the tables missing, keeps the
-- older flow, and shows an answer sent before this as "exact value not recorded".
CREATE TABLE IF NOT EXISTS "evidence_request_decision_fact_submissions" (
	"decision_id" uuid PRIMARY KEY NOT NULL,
	"submission_id" uuid NOT NULL,
	CONSTRAINT "evidence_request_decision_fact_submissions_submission_id_unique" UNIQUE("submission_id")
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "evidence_request_fact_submissions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"evidence_request_id" uuid NOT NULL,
	"round_no" integer NOT NULL,
	"fact_id" uuid NOT NULL,
	"fact_version_id" uuid NOT NULL,
	"field_key_at_send" text NOT NULL,
	"sent_by_account_id" uuid NOT NULL,
	"sent_at" timestamp with time zone DEFAULT now() NOT NULL,
	"grant_id_at_send" uuid,
	"idempotency_key" text NOT NULL,
	CONSTRAINT "evidence_request_fact_submissions_round_unique" UNIQUE("evidence_request_id","round_no"),
	CONSTRAINT "evidence_request_fact_submissions_key_unique" UNIQUE("evidence_request_id","idempotency_key")
);
